function findStepping(low, high) {
  let result = [];
  for (let i = 0; i <= 9; i++) dfs(i);
  function dfs(curr) {
    if (curr > high) return;
    if (curr >= low) result.push(curr);
    if (curr === 0) return;
    let lastDigit = curr % 10;
    if (lastDigit > 0) dfs(curr * 10 + (lastDigit - 1));
    if (lastDigit < 9) dfs(curr * 10 + (lastDigit + 1));
  }
  return result.sort((a,b) => a-b);
}
